/*deleteMasterMpRqReqQuotReceipt_3_DSP*/
UPDATE	KEP_CMC_REQ
SET		REQ_STATUS = 'N',
		KEP_CMC_NOTE = KEP_CMC_NOTE || ' ' || TO_CHAR(SYSDATE, 'YYYY/MM/DD HH24:MI') || ' ' || #{st_cancel_note}, 
		CHANGE_DATE	= SYSDATE,
		CHANGE_USER_ID = #{USR_ID}
WHERE	1=1
AND		BUYER = #{BUYER}
AND		QUOTATION_NO = #{QUOTATION_NO}
AND		QUOTATION_SEQ = #{QUOTATION_SEQ}
AND		REVISION = #{REVISION}
AND		REQ_STATUS NOT IN ('B','C','D','N') -- B:발주후제출, C:승인, D:삭제, N:취소


/*saveMasterMpRqQuotationAtoSDate_DSP*/
	UPDATE KEPQTDT A 
		SET                                    
		    A.ATOS_END_DATE = #{TO_ATOS_END_DATE}
		    , A.ATOS_END_TIME = #{TO_ATOS_END_TIME}   
		    , A.ADMIN_RENEWAL_FLAG = 'Y'
		 WHERE A.BUYER = #{BUYER}                                    
		   AND A.QUOTATION_NO = #{QUOTATION_NO}                                   
		   AND A.QUOTATION_SEQ = #{QUOTATION_SEQ}                                    
		   AND A.REVISION = #{REVISION}
		   AND A.AGENT_REVISION = #{AGENT_REVISION}                                     
		   AND A.STATUS <> 'D'

