/*updateQuotationProceState2_DSP*/
	UPDATE	KEPRQDT A
	SET		A.MSDS_YN = 'Y',
			A.MSDS_NO = '',
			A.MSDS_USER_ID = '',
			A.MSDS_STATUS = 'N'
	WHERE	A.BUYER = #{BUYER}
	AND		A.QUOTATION_NO = #{QUOTATION_NO}
	AND		A.QUOTATION_SEQ = #{QUOTATION_SEQ}
	AND		A.REVISION = #{REVISION}
	AND		A.STATUS <> 'D'

