UPDATE KEPRQDT /*updateMasterMpRqItemChgReq_DSP*/
   SET CMS_REJECT_FLAG = #{CMS_REJECT_YN}
   , ITEM_CHG_REQ_ID = #{ITEM_CHG_REQ_ID}
   , ITEM_CHG_REQ_DATE = SYSDATE
   , ITEM_CHG_REQ_NOTE = #{ITEM_CHG_REQ_NOTE}
   , ITEM_MD_USER_ID =''
   , ITEM_MD_DATE = ''
   , ITEM_CHG_REQ_IMAGE_KEY = #{ITEM_CHG_REQ_IMAGE_KEY}
 WHERE BUYER = #{BUYER}  
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION} 
   AND STATUS <> 'D'


/*updateMasterMpRqKepItemMdReq_DSP*/
UPDATE KEP_ITEM_MD_REQ 
   SET ITEM_MD_STATUS = 'O'
 WHERE BUYER = #{BUYER}  
   AND QUOTATION_NO = #{QUOTATION_NO}    
   AND QUOTATION_SEQ = #{QUOTATION_SEQ}    
   AND REVISION = #{REVISION}
